import { Route } from '@angular/router';
import { MovieList } from './movie-list/movie-list';
import { ScreenPlaceholder } from './screen-placeholder';
import { SeatSelection } from './seat-selection/seat-selection';

export const appRoutes: Route[] = [
  { path: '', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: ScreenPlaceholder },
  { path: 'screenings/:id/checkout', component: ScreenPlaceholder },
  { path: 'confirmation', component: ScreenPlaceholder },
  { path: '**', redirectTo: '' },
];
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  /** ISO date, YYYY-MM-DD */
  date: string;
  /** HH:mm, 24-hour */
  time: string;
  occupiedSeats: string[];
}
const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Formats a local calendar date as YYYY-MM-DD. */
export function toIsoDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/** Parses a strict YYYY-MM-DD string into a local date, or returns null if it is not a real date. */
export function parseIsoDate(value: string | null | undefined): Date | null {
  const match = value?.match(ISO_DATE);
  if (!match) {
    return null;
  }
  const [year, month, day] = match.slice(1).map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day ? date : null;
}

/** Local midnight of the current day. */
export function startOfToday(): Date {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/** English weekday name in full, e.g. "Tuesday". */
export function weekdayName(date: Date): string {
  return date.toLocaleDateString('en-US', { weekday: 'long' });
}

/** Show date as `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
export function formatShowDate(isoDate: string, time: string): string {
  const date = parseIsoDate(isoDate);
  if (!date) {
    return `${isoDate} ${time}`;
  }
  const month = date.toLocaleDateString('en-US', { month: 'short' });
  return `${weekdayName(date)} ${date.getDate()} ${month} ${time}`;
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom, forkJoin, map, switchMap } from 'rxjs';
import { Movie, Screening } from './models';

const API_BASE_URL = 'http://localhost:3000';

export interface MovieListData {
  movies: Movie[];
  screenings: Screening[];
}

export interface ScreeningDetails {
  screening: Screening;
  movie: Movie;
}

@Injectable({ providedIn: 'root' })
export class CinescopeApi {
  private readonly http = inject(HttpClient);

  /** Loads all movies and all screenings in parallel. */
  loadMovieList(): Promise<MovieListData> {
    return firstValueFrom(
      forkJoin({
        movies: this.http.get<Movie[]>(`${API_BASE_URL}/movies`),
        screenings: this.http.get<Screening[]>(`${API_BASE_URL}/screenings`),
      }),
    );
  }

  /** Loads one screening and then its movie. */
  loadScreening(id: number): Promise<ScreeningDetails> {
    return firstValueFrom(
      this.http.get<Screening>(`${API_BASE_URL}/screenings/${id}`).pipe(
        switchMap((screening) =>
          this.http
            .get<Movie>(`${API_BASE_URL}/movies/${screening.movieId}`)
            .pipe(map((movie) => ({ screening, movie }))),
        ),
      ),
    );
  }
}
