<main class="seat-page">
  <h1 class="page-title" data-testid="seat-map-title">Choose your seats</h1>

  @if (loaded()) {
    <p class="show-date" data-testid="seat-map-subtitle">Show Date: {{ showDate() }}</p>
  }

  <p class="seat-limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>

  @if (loaded()) {
    <section class="auditorium">
      <div class="screen-indicator" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.number) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.number">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.number">{{ row.number }}</span>

            @for (segment of row.segments; track $index) {
              @if (segment.kind === 'entrance') {
                <div class="entrance" aria-hidden="true"></div>
              } @else if (segment.kind === 'aisle') {
                <div class="aisle" data-testid="aisle" [attr.data-row]="row.number"></div>
              } @else {
                <div class="block">
                  @for (cell of segment.cells; track cell.column) {
                    @if (cell.kind === 'couch') {
                      <button
                        type="button"
                        class="couch"
                        data-testid="couch"
                        [attr.data-row]="cell.row"
                        [attr.data-column-start]="cell.column"
                        [attr.data-column-end]="cell.columnEnd"
                        [attr.data-state]="displayState(cell)"
                        (click)="toggle(cell)"
                      >{{ cell.column }}-{{ cell.columnEnd }}</button>
                    } @else {
                      <button
                        type="button"
                        class="seat"
                        data-testid="seat"
                        [attr.data-row]="cell.row"
                        [attr.data-column]="cell.column"
                        [attr.data-state]="displayState(cell)"
                        (click)="toggle(cell)"
                      >{{ cell.column }}</button>
                    }
                  }
                </div>
              }
            }

            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.number">{{ row.number }}</span>
          </div>
        }
      </div>
    </section>

    <ul class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <li class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="swatch"></span>
          <span>{{ item.label }}</span>
        </li>
      }
    </ul>

    <section class="selected-seats" data-testid="selected-seats">
      <p class="selected-seats-count" data-testid="selected-seats-count">Selected seats: {{ selectedSeatCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p class="selected-seats-row" data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats }}</p>
      }
    </section>

    <div class="actions">
      <button mat-stroked-button type="button" data-testid="cancel-button">Cancel</button>
      <button mat-flat-button type="button" data-testid="continue-button">Continue</button>
    </div>
  }
</main>
