// Auditorium geometry. Every row is built from the same top-level pieces, so the columns line up:
// row label | left block (or entrance) | aisle | middle block | aisle | right block | row label.
$seat: 36px;
$gap: 4px;
$label: 32px;
$aisle: 2 * $seat + $gap; // two seats wide; a couch is the same width
$block-left: 4 * $seat + 3 * $gap; // columns 1-4 (or the entrance)
$block-middle: 16 * $seat + 15 * $gap; // columns 5-20
$map-width: 2 * $label + 2 * $block-left + 2 * $aisle + $block-middle + 6 * $gap;

.seat-page {
  max-width: 1240px;
  margin: 0 auto;
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.page-title {
  margin: 0;
  font-size: 1.75rem;
  text-align: center;
}

.show-date,
.seat-limit {
  margin: 0;
  text-align: center;
  color: var(--mat-sys-on-surface-variant);
}

.auditorium {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-top: 16px;
}

.screen-indicator {
  width: $map-width;
  padding: 6px 0;
  border-radius: 4px;
  text-align: center;
  letter-spacing: 0.3em;
  background: var(--mat-sys-surface-container-highest);
  color: var(--mat-sys-on-surface);
}

.seat-map {
  width: $map-width;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.seat-row {
  height: $seat;
  display: flex;
  align-items: center;
  gap: $gap;
}

.row-label {
  width: $label;
  flex: none;
  text-align: center;
  font-size: 12px;
  color: var(--mat-sys-on-surface-variant);
}

.entrance {
  width: $block-left;
  flex: none;
}

.aisle {
  width: $aisle;
  flex: none;
}

.block {
  display: flex;
  gap: $gap;
  flex: none;
}

// Background colour of each state, shared by the seats and the legend swatches.
$state-colors: (
  'available': #2e7d32,
  'selected': #f9a825,
  'unavailable': #c62828,
  'accessible': #1565c0,
);

.seat,
.couch {
  flex: none;
  height: $seat;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  color: #fff;
  font: inherit;
  font-size: 12px;
  line-height: 1;

  // There are no hover or focus rules, so the background colour never changes on hover or focus.
  &[data-state='selected'] {
    color: #212121;
  }
}

@each $state, $color in $state-colors {
  .seat[data-state='#{$state}'],
  .couch[data-state='#{$state}'],
  .legend-item[data-state='#{$state}'] .swatch {
    background-color: $color;
  }
}

.seat {
  width: $seat;
}

.couch {
  width: $aisle;
  font-weight: 500;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}

.selected-seats {
  display: flex;
