import { Injectable } from '@angular/core';

/** A selected seat, or a couch covering two adjacent columns of row 15. */
export interface BookedSeat {
  kind: 'seat' | 'couch';
  row: number;
  /** The column of a seat, or the left column of a couch. */
  column: number;
  /** Equal to `column` for a seat, `column + 1` for a couch. */
  columnEnd: number;
}

/** The booking in progress: one screening and the seats chosen for it. */
export interface Booking {
  screeningId: number;
  seats: BookedSeat[];
}

const STORAGE_KEY = 'cinescope.booking';

/** Orders seats by row, then by column. */
export function sortSeats(seats: readonly BookedSeat[]): BookedSeat[] {
  return [...seats].sort((a, b) => a.row - b.row || a.column - b.column);
}

/** Whether two entries are the same seat or couch. */
export function isSameSeat(a: BookedSeat, b: BookedSeat): boolean {
  return a.row === b.row && a.column === b.column;
}

/**
 * Keeps the booking in `sessionStorage`, so it survives a page reload. The storage is read on
 * every call; nothing is cached, so the guards and the screens always see the same booking.
 */
@Injectable({ providedIn: 'root' })
export class BookingService {
  /** The booking in progress, or null when there is none. */
  current(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw === null) {
      return null;
    }
    try {
      const value = JSON.parse(raw) as Partial<Booking> | null;
      if (value && Number.isInteger(value.screeningId) && Array.isArray(value.seats)) {
        return { screeningId: value.screeningId as number, seats: value.seats };
      }
    } catch {
      // A corrupted entry is treated as no booking.
    }
    return null;
  }

  /** Replaces the booking in progress. */
  save(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  /**
   * The booking for a screening: the booking in progress when it belongs to that screening,
   * otherwise a new, empty booking that replaces the previous one.
   */
  openFor(screeningId: number): Booking {
    const current = this.current();
    if (current?.screeningId === screeningId) {
      return current;
    }
    const booking: Booking = { screeningId, seats: [] };
    this.save(booking);
    return booking;
  }

  /** Removes the booking. */
  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }
}

import { BookedSeat } from './booking';

const COUCH_PRICE = 89;

/** Price of one seat or couch in PLN (section 5.4). A couch is priced as a whole. */
export function priceOf(seat: BookedSeat): number {
  if (seat.kind === 'couch') {
    return COUCH_PRICE;
  }
  if (seat.row <= 5) {
    return 25;
  }
  if (seat.row <= 10) {
    return 32;
  }
  return 39;
}

/** Formats an amount in PLN with two decimals, e.g. `25.00 PLN`. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingService } from './booking';

/**
 * Lets the customer enter a screen of the booking in progress: the booking must belong to the
 * screening in the URL and hold at least one seat. Otherwise the customer is redirected to `/`.
 */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingService).current();
  const screeningId = Number(route.paramMap.get('id'));
  const allowed = booking !== null && booking.screeningId === screeningId && booking.seats.length > 0;
  return allowed ? true : inject(Router).createUrlTree(['/']);
};

